const UUID_REGEX =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i

const clampText = (value, maxLen) => {
  if (value === undefined || value === null) return null
  const str = String(value).trim()
  if (!str) return null
  return str.length > maxLen ? str.slice(0, maxLen) : str
}

function extractClientContext(req) {
  const getHeader = (name) => {
    try {
      return req?.get ? req.get(name) : null
    } catch {
      return null
    }
  }

  const sessionIdRaw = clampText(getHeader('x-kubus-session-id'), 64)
  const sessionId = sessionIdRaw && UUID_REGEX.test(sessionIdRaw) ? sessionIdRaw : null

  const screenName = clampText(getHeader('x-kubus-screen-name'), 64)
  const screenRoute = clampText(getHeader('x-kubus-screen-route'), 160)
  const flowStage = clampText(getHeader('x-kubus-flow-stage'), 32)

  const metadata = {}
  if (screenName) metadata.screen_name = screenName
  if (screenRoute) metadata.screen_route = screenRoute
  if (flowStage) metadata.flow_stage = flowStage

  return {
    sessionId,
    metadata: Object.keys(metadata).length ? metadata : null,
  }
}

module.exports = { extractClientContext }

